@RegisterArcadeGame
internal data object UfoJoyrideGame : ArcadeGameDefinition {
    override val title = R.string.arcade_ufo_joyride
    override val description = R.string.arcade_ufo_joyride_sub
    override val icon get() = Icons.Outlined.Ufo
    override val order = 41

    @Composable
    override fun Content(context: ArcadeGameContext, modifier: Modifier) {
        val run = rememberArcadeRun(
            startPlaying = context.initialState.isPlaying,
            create = ::UfoJoyrideRun
        )
        val colors = MaterialTheme.colorScheme
        val palette = remember(colors, context.style) { UfoPalette(colors, context.style) }
        val path = remember { Path() }
        val measurer = rememberTextMeasurer(cacheSize = 48)
        val labels = UfoLabels(
            vehicles = listOf(
                stringResource(R.string.arcade_ufo_vehicle_saucer),
                stringResource(R.string.arcade_ufo_vehicle_bike),
                stringResource(R.string.arcade_ufo_vehicle_walker),
                stringResource(R.string.arcade_ufo_vehicle_gravity),
                stringResource(R.string.arcade_ufo_vehicle_teleporter),
                stringResource(R.string.arcade_ufo_vehicle_bird),
                stringResource(R.string.arcade_ufo_vehicle_dragon),
                stringResource(R.string.arcade_ufo_vehicle_titan),
                stringResource(R.string.arcade_ufo_vehicle_surfer),
                stringResource(R.string.arcade_ufo_vehicle_sled),
            ),
            gadgets = listOf(
                stringResource(R.string.arcade_ufo_gadget_magnet),
                stringResource(R.string.arcade_ufo_gadget_token_magnet),
                stringResource(R.string.arcade_ufo_gadget_crystals),
                stringResource(R.string.arcade_ufo_gadget_gift),
                stringResource(R.string.arcade_ufo_gadget_launch),
                stringResource(R.string.arcade_ufo_gadget_bounce),
                stringResource(R.string.arcade_ufo_gadget_ice),
                stringResource(R.string.arcade_ufo_gadget_ballast),
                stringResource(R.string.arcade_ufo_gadget_slow_missiles),
                stringResource(R.string.arcade_ufo_gadget_empty_lab),
                stringResource(R.string.arcade_ufo_gadget_jammer),
                stringResource(R.string.arcade_ufo_gadget_scanner),
                stringResource(R.string.arcade_ufo_gadget_free_ride),
                stringResource(R.string.arcade_ufo_gadget_lucky),
                stringResource(R.string.arcade_ufo_gadget_cargo),
                stringResource(R.string.arcade_ufo_gadget_discharger),
                stringResource(R.string.arcade_ufo_gadget_companion),
                stringResource(R.string.arcade_ufo_gadget_rings),
                stringResource(R.string.arcade_ufo_gadget_brick),
            ),
            powers = listOf(
                stringResource(R.string.arcade_ufo_power_boost),
                stringResource(R.string.arcade_ufo_power_shield),
                stringResource(R.string.arcade_ufo_power_cash),
                stringResource(R.string.arcade_ufo_power_chrono),
            ),
            utilities = listOf(
                stringResource(R.string.arcade_ufo_revive),
                stringResource(R.string.arcade_ufo_blast),
            )
        )
        ArcadeBoard(context = context, run = run, modifier = modifier) {
            ArcadeField(
                run = run,
                worldSize = Size(480f, 220f),
                lightFeedback = true,
                onPress = { run.press() },
                onRelease = run::stopInput
            ) {
                val shift = if (run.shake > 0f) sin(run.time * 85f) * run.shake else 0f
                translate(left = shift) { drawUfoScene(run, palette, path) }
                val fieldScale = size.width / run.width
                if (fieldScale > 0f) scale(1f / fieldScale, Offset.Zero) {
                    drawUfoHud(run, context.style, palette, labels, measurer, fieldScale)
                }
            }
        }
    }
}

private class UfoLabels(
    val vehicles: List<String>, val gadgets: List<String>,
    val powers: List<String>, val utilities: List<String>
) {
    fun banner(value: Int): String = when (value / 100) {
        0 -> vehicles.getOrElse(value % 100) { "" }
        1 -> powers.getOrElse(value % 100) { "" }
        2 -> gadgets.getOrElse(value % 100) { "" }
        3 -> utilities.getOrElse(value % 100) { "" }
        else -> ""
    }
}

private class UfoPalette(colors: ColorScheme, style: ArcadeStyle) {
    private val dark = colors.surface.luminance() < 0.5f
    val ink =
        lerp(if (dark) colors.surfaceContainerLowest else colors.inverseSurface, colors.scrim, 0.1f)
    val light = if (dark) colors.onSurface else colors.surfaceBright
    val body = lerp(colors.primaryContainer, light, 0.88f)
    val bodyShade = lerp(style.playerColor, colors.surfaceContainerHigh, 0.48f)
    val metal = lerp(bodyShade, body, 0.25f)
    val paint = style.playerColor
    val glass = lerp(colors.primaryContainer, body, 0.38f)
    val window = lerp(ink, colors.surfaceContainerHigh, 0.3f)
    val gold = style.accentColor
    val goldShade = lerp(gold, ink, 0.35f)
    val goldLight = lerp(gold, light, 0.55f)
    val danger = style.hazardColor
    val electric = style.playerColor
    val artColors = listOf(
        ink, bodyShade, metal, body, light, lerp(paint, ink, 0.35f), paint,
        lerp(paint, body, 0.4f), window, glass, goldShade, gold
    )
    val dust = lerp(colors.outline, colors.surface, 0.55f)
    val panel = colors.surfaceContainer
    val hud = colors.surfaceContainerHigh.copy(alpha = 0.94f)
    val text = colors.onSurface
    val outline = colors.outlineVariant
    val pickup = colors.primaryContainer
    val onPickup = colors.onPrimaryContainer
    val steel = lerp(colors.surfaceContainerHighest, colors.secondary, 0.08f)
    val steelLight = lerp(steel, colors.outline, 0.3f)
    val steelShade = lerp(colors.surfaceContainerLow, ink, 0.12f)
    val crate = lerp(bodyShade, body, 0.3f)
    val crateLight = lerp(crate, body, 0.4f)
    val crateShade = lerp(bodyShade, ink, 0.25f)
    val skies = arrayOf(
        lerp(colors.surfaceContainerLow, paint, 0.025f),
        colors.surfaceContainer,
        lerp(colors.surfaceContainerLow, colors.secondary, 0.035f),
        lerp(colors.surfaceContainer, paint, 0.025f),
        lerp(colors.surfaceContainerLow, ink, 0.12f)
    )
    private val images = mutableMapOf<UfoArt, ImageBitmap>()
    private val technicians = mutableMapOf<UfoArt, ImageBitmap>()
    val playerPaint = Paint()
    val coin by lazy {
        image(16, 16) {
            drawArcadeSprite(UfoCoinRim, goldShade, 0f, 0f)
            drawArcadeSprite(UfoCoinFace, gold, 0f, 0f)
            drawArcadeSprite(UfoCoinGlint, goldLight, 0f, 0f)
            pixelRect(goldShade, 7f, 5f, 2f, 6f)
        }
    }
    val crystal by lazy {
        image(12, 16) {
            drawArcadeSprite(UfoCrystal, ink, 0f, 0f)
            drawArcadeSprite(UfoCrystalFace, glass, 0f, 0f)
            pixelRect(body, 4f, 3f, 4f, 2f)
        }
    }
    val zapper by lazy {
        image(22, 22) {
            drawArcadeSprite(UfoZapperCap, ink, 0f, 0f)
            pixelCircle(metal, 8f, Offset(11f, 11f))
            pixelCircle(danger, 6f, Offset(11f, 11f))
            pixelCircle(light, 3f, Offset(11f, 11f))
            pixelRect(body, 6f, 4f, 6f, 2f)
        }
    }

    fun sprite(art: UfoArt, technician: Boolean = false): ImageBitmap =
        (if (technician) technicians else images).getOrPut(art) {
            image(art.width, art.height) {
                for ((index, layer) in art.layers) {
                    val color = if (technician) when (index) {
                        5 -> bodyShade
                        6 -> body
                        7 -> light
                        else -> artColors[index]
                    } else artColors[index]
                    drawArcadeSprite(layer, color, 0f, 0f)
                }
            }
        }

    private fun image(width: Int, height: Int, draw: DrawScope.() -> Unit): ImageBitmap =
        ImageBitmap(width, height).also { bitmap ->
            CanvasDrawScope().draw(
                Density(1f),
                LayoutDirection.Ltr,
                Canvas(bitmap),
                Size(width.toFloat(), height.toFloat()),
                draw
            )
        }
}

