private fun DrawScope.ufoLine(color: Color, start: Offset, end: Offset, strokeWidth: Float) {
    val width = (strokeWidth / 2f).roundToInt().coerceAtLeast(1) * 2f
    val ax = (start.x / 2f).roundToInt() * 2f
    val ay = (start.y / 2f).roundToInt() * 2f
    val bx = (end.x / 2f).roundToInt() * 2f
    val by = (end.y / 2f).roundToInt() * 2f
    if (ax == bx) pixelRect(
        color,
        ax - width / 2f,
        minOf(ay, by) - width / 2f,
        width,
        abs(by - ay) + width
    )
    else if (ay == by) pixelRect(
        color,
        minOf(ax, bx) - width / 2f,
        ay - width / 2f,
        abs(bx - ax) + width,
        width
    )
    else {
        val steps = ceil(maxOf(abs(bx - ax), abs(by - ay)) / 2f).toInt().coerceAtLeast(1)
        for (i in 0..steps) {
            val t = i.toFloat() / steps
            val x = ((ax + (bx - ax) * t) / 2f).roundToInt() * 2f
            val y = ((ay + (by - ay) * t) / 2f).roundToInt() * 2f
            pixelRect(color, x - width / 2f, y - width / 2f, width, width)
        }
    }
}

private fun DrawScope.drawUfoScene(run: UfoJoyrideRun, p: UfoPalette, path: Path) {
    drawUfoBackground(run, p)
    for (scientist in run.scientists) {
        val at = Offset(scientist.x, scientist.y)
        rotate(scientist.angle, at) {
            drawUfoTechnician(at, p, sin(scientist.age * 14f) * 4f, flying = true)
        }
    }
    for (pickup in run.pickups) drawUfoPickup(pickup, run, p)
    if (run.cashPigX > -30f && run.cashPigX < run.width + 30f) {
        val art = UfoCashPigArt[(run.time * 8f).toInt() % UfoCashPigArt.size]
        drawUfoArt(art, p, Offset(run.cashPigX - art.width / 2f, run.cashPigY - art.height / 2f))
    }
    for (hazard in run.hazards) drawUfoHazard(hazard, run, p, path)
    if (run.has(UfoGadget.Companion)) {
        val dog = UfoCompanionArt[(run.time * 12f).toInt() % UfoCompanionArt.size]
        drawUfoArt(dog, p, Offset(run.playerX - 48f - dog.width / 2f, run.ground + 7f - dog.height))
    }
    for (particle in run.particles) {
        val life = (particle.life / particle.duration).coerceIn(0f, 1f)
        val color = when (particle.kind) {
            0 -> p.electric; 1 -> p.gold; else -> p.dust
        }
        if (particle.kind == 3) {
            ufoImage(p.coin, Offset(particle.x - 8f, particle.y - 8f), alpha = life)
            continue
        }
        val side = if (life > 0.5f) 4f else 2f
        pixelRect(
            color.copy(alpha = life),
            particle.x.roundToInt().toFloat(),
            particle.y.roundToInt().toFloat(),
            side,
            side
        )
    }
    if (run.vehicle == UfoVehicle.Teleporter && !run.crashing) {
        val target = Offset(minOf(run.width - 26f, run.playerX + 48f), run.targetY)
        val art = UfoVehicleArt.getValue(UfoVehicle.Teleporter).first()
        drawUfoArt(art, p, target - Offset(art.width / 2f, art.height / 2f), alpha = 0.2f)
        for (side in intArrayOf(-1, 1)) {
            pixelRect(p.electric, target.x + side * 18f - 2f, target.y - 14f, 4f, 8f)
            pixelRect(p.electric, target.x + side * 18f - 2f, target.y + 6f, 4f, 8f)
        }
    }
    val visible =
        run.phase != ArcadePhase.Running || run.immunity <= 0f || (run.time * 15f).toInt() % 3 != 0 || run.boost > 0f || run.transforming > 0f
    if (visible) {
        if (run.pressed && run.vehicle == UfoVehicle.Saucer && !run.crashing) {
            val beamTop = run.y + 8f
            val beamBottom = run.ground + 7f
            val beamHeight = (beamBottom - beamTop).coerceAtLeast(0f)
            if (beamHeight > 0f) {
                val beamX = run.playerX.roundToInt().toFloat()
                pixelRect(p.electric.copy(alpha = 0.3f), beamX - 4f, beamTop, 8f, beamHeight)
                pixelRect(p.electric.copy(alpha = 0.65f), beamX - 2f, beamTop, 4f, beamHeight)
                var pulseY = beamTop + (run.time * 420f % 24f)
                while (pulseY < beamBottom) {
                    pixelRect(
                        p.light,
                        beamX - 3f,
                        pulseY.roundToInt().toFloat(),
                        6f,
                        minOf(6f, beamBottom - pulseY)
                    )
                    pulseY += 24f
                }
                pixelRect(p.electric.copy(alpha = 0.4f), beamX - 12f, beamBottom - 2f, 24f, 4f)
                repeat(7) { i ->
                    val phase = (run.time * 7f + i / 7f) % 1f
                    val direction = if (i % 2 == 0) -1f else 1f
                    pixelRect(
                        p.electric.copy(alpha = 1f - phase), run.playerX + direction * phase * 18f,
                        beamBottom - sin(phase * PI.toFloat()) * (4f + i % 3 * 3f), 2f, 2f
                    )
                }
            }
        }
        if (run.boost > 0f) repeat(4) { i ->
            val x = run.playerX - 26f - i * 13f
            ufoLine(
                p.electric.copy(alpha = 0.35f - i * 0.07f),
                Offset(x, run.y - 6f),
                Offset(x - 18f, run.y - 6f),
                3f
            )
            ufoLine(
                p.gold.copy(alpha = 0.3f - i * 0.06f),
                Offset(x, run.y + 6f),
                Offset(x - 14f, run.y + 6f),
                2f
            )
        }
        drawUfoPlayer(run, p)
    }
    if (run.shield > 0 && !run.crashing) {
        val radius = maxOf(run.radiusX, run.radiusY) + 8f
        pixelCircle(p.electric.copy(alpha = 0.08f), radius, Offset(run.playerX, run.y))
        pixelCircle(
            p.electric.copy(alpha = 0.65f),
            radius,
            Offset(run.playerX, run.y),
            style = Stroke(2f)
        )
    }
    if (run.transforming > 0f) {
        repeat(4) { i ->
            val angle = i * PI.toFloat() / 2f
            val distance = 18f + (1f - run.transforming) * 25f
            pixelRect(
                p.body.copy(alpha = run.transforming.coerceAtMost(1f)),
                run.playerX + cos(angle) * distance - 2f, run.y + sin(angle) * distance - 2f, 4f, 4f
            )
        }
    }
    if (run.chrono > 0f) drawRect(
        p.electric.copy(alpha = 0.045f),
        size = Size(run.width, run.height)
    )
    if (run.flash > 0f) drawRect(
        p.light.copy(alpha = run.flash.coerceAtMost(0.25f)),
        size = Size(run.width, run.height)
    )
}

private fun DrawScope.drawUfoBackground(run: UfoJoyrideRun, p: UfoPalette) {
    val sky = lerp(p.skies[(run.biome + 4) % 5], p.skies[run.biome], run.biomeBlend)
    drawRect(
        Brush.verticalGradient(
            listOf(sky, lerp(sky, p.steel, 0.08f)),
            startY = run.ceiling, endY = run.ground
        ), size = Size(run.width, run.height)
    )
    val scroll = run.travelled * 0.72
    val first = floor(scroll / 176.0).toLong() - 1
    val last = first + (run.width / 176f).toInt() + 2
    for (column in first..last) {
        val x = (column * 176.0 - scroll).toFloat()
        var top = run.ceiling + 10f
        var row = 0
        while (top < run.ground) {
            val height = minOf(140f, run.ground - top)
            val at = Offset(x + 10f, top)
            val bounds = Size(154f, height)
            pixelRect(lerp(sky, p.ink, 0.08f), at.x, at.y, bounds.width, bounds.height)
            if (height > 66f && (column + row) % 5L == 2L) {
                val vent = Offset(x + 61f, top + 35f)
                pixelRect(p.window.copy(alpha = 0.3f), vent.x, vent.y, 40f, 28f)
                pixelRect(p.metal.copy(alpha = 0.18f), vent.x, vent.y, 40f, 4f)
                repeat(3) { slot ->
                    pixelRect(
                        p.metal.copy(alpha = 0.18f),
                        vent.x + 6f,
                        vent.y + 8f + slot * 6f,
                        28f,
                        3f
                    )
                }
            }
            top += 148f
            row++
        }
        pixelRect(
            p.bodyShade.copy(alpha = 0.22f),
            x,
            run.ceiling + 10f,
            6f,
            run.ground - run.ceiling - 10f
        )
    }
    pixelRect(p.steelShade, 0f, run.ceiling + 1f, run.width, 6f)
    var clamp = -(scroll % 88.0).toFloat()
    while (clamp < run.width) {
        pixelRect(p.metal.copy(alpha = 0.4f), clamp, run.ceiling, 6f, 10f)
        clamp += 88f
    }
    val travelled = run.travelled
    var section = floor((travelled - 100.0) / 240.0).toLong()
    while (section * 240.0 - travelled < run.width + 100f) {
        val x = (section * 240.0 - travelled).toFloat()
        val floorY = run.ground + 7f
        pixelRect(p.steelShade, x + 54f, run.ceiling + 4f, 24f, 8f)
        pixelRect(p.body.copy(alpha = 0.5f), x + 58f, run.ceiling + 10f, 16f, 2f)
        when (section % 4L) {
            0L -> drawUfoRack(x + 10f, floorY, p, section)
            1L -> {
                drawUfoCrate(x + 12f, floorY - 26f, 30f, 26f, p)
                drawUfoCrate(x + 43f, floorY - 38f, 26f, 38f, p)
            }

            2L -> {
                pixelRect(p.ink.copy(alpha = 0.5f), x + 10f, floorY - 65f, 42f, 65f)
                pixelRect(p.metal, x + 12f, floorY - 64f, 38f, 4f)
                pixelRect(p.bodyShade, x + 12f, floorY - 60f, 38f, 60f)
                pixelRect(p.window, x + 17f, floorY - 52f, 28f, 48f)
                pixelRect(p.steelShade, x + 31f, floorY - 52f, 2f, 48f)
                pixelRect(p.body.copy(alpha = 0.6f), x + 17f, floorY - 58f, 28f, 3f)
            }

            else -> Unit
        }
        if (!run.has(UfoGadget.EmptyLab) && run.scientists.none { it.id == section }) {
            val scared = abs(x + 145f - run.playerX) < 75f
            val stride = sin(run.time * if (scared) 17f else 6f) * 3f
            drawUfoTechnician(Offset(x + 145f, run.ground - 5f), p, stride, scared = scared)
        }
        section++
    }
    val floorTop = run.ground + 8f
    pixelRect(p.panel, 0f, floorTop, run.width, run.height - floorTop)
    pixelRect(lerp(p.paint, p.body, 0.48f), 0f, floorTop, run.width, 2f)
    pixelRect(p.bodyShade, 0f, floorTop + 2f, run.width, 3f)
    var tile = -(travelled % 48.0).toFloat() - 48f
    while (tile < run.width) {
        pixelRect(p.bodyShade.copy(alpha = 0.4f), tile + 4f, floorTop + 7f, 6f, 2f)
        pixelRect(p.bodyShade.copy(alpha = 0.3f), tile + 20f, floorTop + 10f, 4f, 2f)
        tile += 48f
    }
    pixelRect(p.steelShade, 0f, run.height - 4f, run.width, 4f)
    pixelRect(p.steel, 0f, run.ceiling - 6f, run.width, 6f)
    pixelRect(p.outline.copy(alpha = 0.25f), 0f, run.ceiling, run.width, 1f)
    if (run.vehicle == UfoVehicle.Surfer) for (i in 0..(run.width / 10f).toInt()) {
        val wave = sin(i * 0.8f + run.time * 5f) * 2f
        pixelRect(p.electric.copy(alpha = 0.18f), i * 10f, run.ground + wave, 10f, 9f - wave)
        pixelRect(p.glass.copy(alpha = 0.4f), i * 10f, run.ground + wave, 7f, 1f)
    }
}

private fun DrawScope.drawUfoCrate(x: Float, y: Float, width: Float, height: Float, p: UfoPalette) {
    pixelRect(p.ink.copy(alpha = 0.4f), x + 3f, y + 3f, width, height)
    pixelRect(p.crateShade, x, y, width, height)
    pixelRect(p.crate, x + 1f, y + 1f, width - 3f, height - 3f)
    pixelRect(p.crateLight, x + 1f, y + 1f, width - 3f, 2f)
    pixelRect(p.crateLight, x + 1f, y + 1f, 2f, height - 3f)
    ufoLine(p.crateShade, Offset(x + 5f, y + 5f), Offset(x + width - 6f, y + height - 5f), 2.5f)
    ufoLine(p.crateShade, Offset(x + width - 5f, y + 5f), Offset(x + 5f, y + height - 5f), 2.5f)
    pixelRect(p.crateShade, x + 4f, y + 4f, width - 8f, 1f)
    pixelRect(p.crateShade, x + 4f, y + height - 5f, width - 8f, 1f)
    pixelRect(p.body.copy(alpha = 0.7f), x + width * 0.3f, y + height * 0.42f, width * 0.4f, 6f)
    pixelRect(
        p.ink.copy(alpha = 0.3f),
        x + width * 0.32f,
        y + height * 0.42f + 2f,
        width * 0.3f,
        1f
    )
}

private fun DrawScope.drawUfoRack(x: Float, floor: Float, p: UfoPalette, index: Long) {
    val top = floor - 83f
    pixelRect(p.ink.copy(alpha = 0.3f), x + 5f, top + 4f, 78f, 79f)
    for (row in 0..3) {
        val shelf = floor - row * 22f
        pixelRect(p.steelShade, x, shelf - 3f, 74f, 3f)
        pixelRect(p.steelLight.copy(alpha = 0.65f), x, shelf - 3f, 74f, 1f)
        if (row < 3) {
            val shift = if ((index + row) % 2L == 0L) 3f else 24f
            drawUfoCrate(x + shift, shelf - 20f, 22f, 17f, p)
            if (row != 1) drawUfoCrate(x + 48f, shelf - 16f, 18f, 13f, p)
        }
    }
    for (side in floatArrayOf(x, x + 72f)) {
        pixelRect(p.ink, side - 2f, top, 5f, 83f)
        pixelRect(p.steelShade, side - 1f, top, 3f, 83f)
        pixelRect(p.steelLight, side - 1f, top, 1f, 83f)
    }
}

private fun DrawScope.drawUfoTechnician(
    at: Offset,
    p: UfoPalette,
    step: Float,
    scared: Boolean = false,
    flying: Boolean = false
) {
    val frame =
        if (flying) 3 else (abs(step) * if (scared) 2f else 1f).toInt() % UfoScientistArt.size
    val art = UfoScientistArt[frame]
    val origin = at - Offset(art.width / 2f, 14f)
    ufoImage(p.sprite(art, technician = true), origin)
}

private fun DrawScope.drawUfoHazard(h: UfoHazard, run: UfoJoyrideRun, p: UfoPalette, path: Path) {
    if (h.x > run.width + 100f || h.x < -100f || h.disabled && h.kind != UfoHazardKind.Missile) return
    val center = Offset(h.x, h.y)
    when (h.kind) {
        UfoHazardKind.Missile -> {
            if (h.age <= 1.15f) {
                val warning = Offset(run.width - 22f, h.y - 9f)
                val alpha =
                    if (h.locked) 1f else if ((h.age * 12f).toInt() % 2 == 0) 0.85f else 0.4f
                drawArcadeSprite(UfoWarning, p.danger.copy(alpha = alpha), warning.x, warning.y)
                pixelRect(p.light, warning.x + 10f, warning.y + 3f, 3f, 7f)
                pixelRect(p.light, warning.x + 10f, warning.y + 12f, 3f, 3f)
            } else rotate(if (h.disabled) (h.age - 1.15f) * 150f else 0f, center) {
                if (!h.disabled) {
                    pixelRect(
                        p.gold,
                        h.x + 12f,
                        h.y - 3f,
                        8f + (sin(run.time * 45f) * 4f).roundToInt(),
                        6f
                    )
                    pixelRect(p.goldLight, h.x + 12f, h.y - 1f, 7f, 2f)
                }
                drawArcadeSprite(UfoMissile, p.ink, h.x - 15f, h.y - 8f)
                pixelRect(if (h.disabled) p.dust else p.body, h.x - 8f, h.y - 4f, 18f, 8f)
                pixelRect(if (h.disabled) p.metal else p.danger, h.x - 11f, h.y - 3f, 4f, 6f)
                pixelRect(p.metal, h.x + 6f, h.y - 7f, 5f, 3f)
                pixelRect(p.metal, h.x + 6f, h.y + 4f, 5f, 3f)
            }
        }

        UfoHazardKind.Laser -> {
            val active = h.age > 0.95f && h.age < 2.65f
            val left = h.x - 90f
            if (active) {
                pixelRect(p.danger, left, h.y - 3f, 180f, 6f)
                pixelRect(p.light, left, h.y - 1f, 180f, 2f)
            } else if (h.age < 0.95f) {
                var x = left
                while (x < h.x + 90f) {
                    pixelRect(
                        p.danger.copy(alpha = if ((h.age * 10f).toInt() % 2 == 0) 0.6f else 0.25f),
                        x,
                        h.y - 1f,
                        6f,
                        2f
                    )
                    x += 14f
                }
            }
            for (end in floatArrayOf(left, h.x + 90f)) {
                pixelRect(p.ink, end - 6f, h.y - 12f, 12f, 24f)
                pixelRect(p.bodyShade, end - 4f, h.y - 10f, 8f, 20f)
                pixelRect(p.body, end - 4f, h.y - 10f, 8f, 3f)
                pixelRect(p.danger, end - 2f, h.y - 5f, 4f, 10f)
            }
        }

        else -> {
            val direction = h.direction
            val a = center - direction * (h.length / 2f)
            val b = center + direction * (h.length / 2f)
            val normal = Offset(-direction.y, direction.x)
            val count = ceil(h.length / 4f).toInt().coerceAtLeast(1)
            path.rewind()
            for (i in 0..count) {
                val point =
                    a + (b - a) * (i.toFloat() / count) + normal * ((sin(run.time * 34f + i * 2f) * 2f).roundToInt() * 2f)
                val x = (point.x / 2f).roundToInt() * 2f
                val y = (point.y / 2f).roundToInt() * 2f
                path.addRect(Rect(x - 2f, y - 2f, x + 2f, y + 2f))
            }
            drawPath(path, p.danger)
            for (point in arrayOf(a, b)) {
                drawArcadeSprite(
                    UfoZapperCap,
                    p.ink,
                    point.x.roundToInt() - 11f,
                    point.y.roundToInt() - 11f
                )
                pixelCircle(p.metal, 8f, point)
                pixelCircle(p.danger, 6f, point)
                pixelCircle(p.light, 3f, point)
                pixelRect(p.body, point.x - 5f, point.y - 7f, 6f, 2f)
            }
        }
    }
}

private fun DrawScope.drawUfoPickup(item: UfoPickup, run: UfoJoyrideRun, p: UfoPalette) {
    if (item.x < -25f || item.x > run.width + 25f) return
    val at = Offset(item.x.roundToInt().toFloat(), item.y.roundToInt().toFloat())
    when (item.kind) {
        UfoPickupKind.Coin -> {
            ufoImage(p.coin, at - Offset(8f, 8f))
        }

        UfoPickupKind.Crystal -> {
            ufoImage(p.crystal, at - Offset(6f, 8f))
        }

        UfoPickupKind.Ring -> {
            pixelCircle(p.electric, 12f, at, style = Stroke(3f))
            drawUfoSymbol(1, at, p.body)
        }

        UfoPickupKind.Gadget -> {
            val art = UfoGadgetArt[item.variant % UfoGadgetArt.size]
            drawUfoArt(art, p, at - Offset(12f, 12f))
        }

        UfoPickupKind.Cargo -> {
            val art = UfoCashPigArt[(run.time * 8f).toInt() % UfoCashPigArt.size]
            drawUfoArt(art, p, at - Offset(art.width / 2f, art.height / 2f))
        }

        UfoPickupKind.Vehicle -> {
            drawArcadeSprite(UfoCrateRim, p.ink, at.x - 16f, at.y - 16f)
            drawArcadeSprite(UfoCrateFace, p.electric, at.x - 14f, at.y - 14f)
            pixelRect(p.pickup, at.x - 11f, at.y - 11f, 22f, 22f)
            if (run.has(UfoGadget.Scanner)) {
                val vehicle = when (item.variant % 8) {
                    6 -> UfoVehicle.Surfer
                    7 -> UfoVehicle.Sled
                    else -> UfoVehicle.entries[1 + item.variant % 8]
                }
                val art = UfoVehicleArt.getValue(vehicle).first()
                scale(20f / maxOf(art.width, art.height), at) {
                    drawUfoArt(art, p, at - Offset(art.width / 2f, art.height / 2f))
                }
            } else drawUfoSymbol(0, at, p.onPickup)
            val position = (run.time * 5f).toInt() % 4
            rotate(position * 90f, at) { pixelRect(p.body, at.x - 7f, at.y - 15f, 8f, 2f) }
        }

        else -> {
            pixelCircle(p.ink, 15f, at)
            pixelCircle(p.electric, 14f, at)
            pixelCircle(p.pickup, 11f, at)
            val symbol = when (item.kind) {
                UfoPickupKind.Boost -> 1
                UfoPickupKind.Shield -> 2
                UfoPickupKind.Cash, UfoPickupKind.Cargo -> 3
                UfoPickupKind.Chrono -> 4
                UfoPickupKind.Part -> 6 + item.variant % 3
                UfoPickupKind.Revive -> 9
                UfoPickupKind.Blast -> 10
                else -> 11
            }
            drawUfoSymbol(symbol, at, p.onPickup)
        }
    }
}

private fun DrawScope.drawUfoSymbol(kind: Int, at: Offset, color: Color) {
    drawArcadeSprite(UfoSymbols[kind.coerceIn(UfoSymbols.indices)], color, at.x - 8f, at.y - 8f)
}

private fun DrawScope.ufoImage(image: ImageBitmap, at: Offset, alpha: Float = 1f) {
    drawImage(
        image,
        dstOffset = IntOffset(at.x.roundToInt(), at.y.roundToInt()),
        alpha = alpha,
        filterQuality = FilterQuality.None
    )
}

private fun DrawScope.drawUfoArt(art: UfoArt, p: UfoPalette, at: Offset, alpha: Float = 1f) {
    val x = at.x.roundToInt().toFloat()
    val y = at.y.roundToInt().toFloat()
    ufoImage(p.sprite(art), Offset(x, y), alpha)
}

private val UfoAlienHead = ArcadeSprite(
    12, 12,
    "M3 0H9V1H11V3H12V7H10V10H8V12H4V10H2V8H0V3H1V1H3Z"
)
private val UfoAlienSmallHead = ArcadeSprite(
    8, 8,
    "M2 0H6V1H7V2H8V5H7V6H6V8H2V7H1V6H0V2H1V1H2Z"
)

private fun DrawScope.drawUfoAlien(at: Offset, p: UfoPalette, small: Boolean, body: Boolean) {
    val x = at.x.roundToInt().toFloat()
    val y = at.y.roundToInt().toFloat()
    if (body) {
        pixelRect(p.ink, x - 3f, y + 5f, 7f, 10f)
        pixelRect(p.bodyShade, x - 3f, y + 5f, 6f, 6f)
        pixelRect(p.body, x - 2f, y + 5f, 4f, 2f)
        pixelRect(p.paint, x + 2f, y + 7f, 5f, 2f)
        pixelRect(p.ink, x - 4f, y + 14f, 4f, 3f)
        pixelRect(p.ink, x + 2f, y + 13f, 5f, 3f)
    }
    val half = if (small) 4f else 6f
    val sprite = if (small) UfoAlienSmallHead else UfoAlienHead
    drawArcadeSprite(sprite, p.ink, x - half, y - half + 1f)
    drawArcadeSprite(sprite, lerp(p.paint, p.body, 0.28f), x - half, y - half)
    pixelRect(p.ink, x - half + 1f, y - 1f, if (small) 2f else 3f, if (small) 2f else 3f)
    pixelRect(p.ink, x + 1f, y - 1f, if (small) 2f else 3f, if (small) 2f else 3f)
    pixelRect(p.body, x - half + 2f, y - half + 1f, if (small) 2f else 4f, 1f)
}

private fun DrawScope.drawUfoPlayer(run: UfoJoyrideRun, p: UfoPalette) {
    val at = Offset(run.playerX, run.y)
    pixelRect(p.ink.copy(alpha = 0.12f), at.x - 14f, run.ground + 5f, 28f, 4f)
    if (run.crashing) {
        if (run.has(UfoGadget.Bounce)) {
            pixelCircle(p.goldShade, 23f, at)
            pixelCircle(p.gold.copy(alpha = 0.25f), 20f, at)
            pixelCircle(p.goldLight, 23f, at, style = Stroke(3f))
        } else if (run.has(UfoGadget.Ice)) {
            pixelRect(p.glass.copy(alpha = 0.3f), at.x - 22f, at.y - 18f, 44f, 36f)
            pixelRect(p.body, at.x - 22f, at.y - 18f, 44f, 3f)
            pixelRect(p.glass, at.x - 22f, at.y - 18f, 3f, 36f)
        }
        rotate(run.tilt, at) { drawUfoSaucer(at, run, p, damaged = true) }
        return
    }
    if (run.vehicle == UfoVehicle.Saucer) {
        rotate(run.tilt, at) { drawUfoSaucer(at, run, p) }
        return
    }
    if (run.vehicle == UfoVehicle.Dragon) {
        for (i in 6 downTo 1) {
            val part = if (i == 2) UfoDragonSaddleArt else UfoDragonBodyArt
            val tail =
                at + Offset(-i * 14f, (sin(run.time * 7f - i * 0.6f) * 6f).roundToInt().toFloat())
            drawUfoArt(part, p, tail - Offset(part.width / 2f, part.height / 2f))
            if (i == 2) {
                val target = tail - Offset(0f, 11f)
                val progress =
                    if (run.transfer) (1f - run.transforming / 0.65f).coerceIn(0f, 1f) else 1f
                val from = at - Offset(0f, 4f)
                drawUfoAlien(
                    from + (target - from) * progress - Offset(
                        0f,
                        sin(progress * PI.toFloat()) * 24f
                    ), p, small = false, body = true
                )
            }
        }
    }
    val frames = UfoVehicleArt.getValue(run.vehicle)
    val index = if (run.vehicle == UfoVehicle.Titan) {
        (run.titanHand * frames.lastIndex).roundToInt().coerceIn(frames.indices)
    } else (run.time * if (run.vehicle == UfoVehicle.Bird && run.velocity < 0f) 16f else 10f).toInt() % frames.size
    val art = frames[index]
    val grounded = run.vehicle in listOf(
        UfoVehicle.Bike,
        UfoVehicle.Walker,
        UfoVehicle.Titan,
        UfoVehicle.Surfer,
        UfoVehicle.Sled
    )
    val anchorY = if (grounded) art.height - run.radiusY else art.height / 2f
    val origin = at - Offset(art.width / 2f, anchorY)
    val angle = when (run.vehicle) {
        UfoVehicle.Gravity -> if (run.gravityUp) 180f else 0f
        UfoVehicle.Titan, UfoVehicle.Walker, UfoVehicle.Teleporter -> 0f
        else -> run.tilt * 0.5f
    }
    rotate(angle, at) {
        fun pilot() {
            art.pilot?.let { seat ->
                val target = origin + seat
                val progress =
                    if (run.transfer) (1f - run.transforming / 0.65f).coerceIn(0f, 1f) else 1f
                val from = at - Offset(0f, 4f)
                val position = from + (target - from) * progress - Offset(
                    0f,
                    sin(progress * PI.toFloat()) * 24f
                )
                drawUfoAlien(
                    position,
                    p,
                    art.headSize == 8,
                    body = run.vehicle == UfoVehicle.Surfer || run.vehicle == UfoVehicle.Sled
                )
            }
        }

        val behind =
            run.vehicle == UfoVehicle.Walker || run.vehicle == UfoVehicle.Bird || run.vehicle == UfoVehicle.Sled
        if (behind) pilot()
        drawUfoArt(art, p, origin)
        if (!behind) pilot()
    }
    if (run.transfer && run.transforming > 0f) {
        val progress = (1f - run.transforming / 0.65f).coerceIn(0f, 1f)
        val ship = at + Offset(-progress * 55f, progress * 25f)
        drawArcadeSprite(UfoHull, p.metal.copy(alpha = 1f - progress), ship.x - 19f, ship.y - 9f)
        drawArcadeSprite(UfoDome, p.glass.copy(alpha = 1f - progress), ship.x - 19f, ship.y - 9f)
    }
    if (run.vehicle == UfoVehicle.Sled) {
        for (i in 0..1) {
            val deer = UfoReindeerArt[(run.time * 10f + i).toInt() % UfoReindeerArt.size]
            val position =
                at + Offset(38f + i * 24f, -8f + (sin(run.time * 6f + i) * 4f).roundToInt())
            ufoLine(p.metal, at + Offset(22f, 4f), position + Offset(0f, 6f), 2f)
            drawUfoArt(deer, p, position - Offset(deer.width / 2f, deer.height / 2f))
        }
    }
    if (run.vehicle == UfoVehicle.Dragon && run.pressed) {
        for (i in 0..6) {
            val x = at.x + 14f + i * 5f
            val height = 14f - i + (sin(run.time * 36f + i) * 3f).roundToInt()
            pixelRect(p.danger, x, at.y + 7f - height / 2f, 6f, height)
            if (i < 5) pixelRect(p.goldLight, x, at.y + 5f, 5f, 4f)
        }
    }
}

private fun DrawScope.drawUfoSaucer(
    at: Offset,
    run: UfoJoyrideRun,
    p: UfoPalette,
    damaged: Boolean = false
) {
    val x = at.x - 19f
    val y = at.y - 9f
    drawArcadeSprite(UfoHull, p.ink, x, y)
    drawArcadeSprite(UfoRim, if (damaged) p.dust else p.metal, x, y)
    drawArcadeSprite(UfoDome, if (damaged) p.window else p.glass, x, y)
    pixelRect(p.paint, at.x - 4f, at.y - 5f, 8f, 4f)
    pixelRect(p.ink, at.x - 3f, at.y - 4f, 2f, 2f)
    pixelRect(p.ink, at.x + 2f, at.y - 4f, 2f, 2f)
    drawArcadeSprite(UfoGlint, p.light.copy(alpha = 0.8f), x, y)
    repeat(5) { i ->
        val color = if ((i + (run.time * 7).toInt()) % 5 == 0) p.gold else p.paint
        pixelRect(if (damaged) p.ink else color, x + 7f + i * 5f, y + 11f, 3f, 2f)
    }
    pixelRect(p.ink, at.x - 6f, at.y + 8f, 12f, 2f)
}

private fun DrawScope.drawUfoHud(
    run: UfoJoyrideRun, style: ArcadeStyle, p: UfoPalette, labels: UfoLabels,
    measurer: TextMeasurer, fieldScale: Float
) {
    if (run.phase == ArcadePhase.Ready) return
    val inset = 12.dp.toPx()
    val available = minOf(148.dp.toPx(), run.width * fieldScale * 0.43f)
    val cell = 36.dp.toPx()
    val textStyle = style.scoreTextStyle.copy(fontSize = 10.sp, color = p.text)
    var x = inset
    var y = 22.dp.toPx()
    var count = 0

    fun indicator(symbol: Int, progress: Float = 0f, value: String = "") {
        if (x + cell > inset + available && count > 0) {
            x = inset
            y += 15.dp.toPx()
        }
        translate(x + 5.dp.toPx(), y) {
            scale(density * 0.68f, Offset.Zero) {
                drawUfoSymbol(symbol, Offset.Zero, style.playerColor)
            }
        }
        val start = x + 14.dp.toPx()
        if (value.isNotEmpty()) {
            val layout = measurer.measure(value, textStyle, maxLines = 1)
            drawText(layout, p.text, Offset(start, y - layout.size.height / 2f))
        } else if (progress > 0f) {
            val bar = Size(17.dp.toPx(), 3.dp.toPx())
            val at = Offset(start, y - bar.height / 2f)
            drawRect(style.detailColor.copy(alpha = 0.3f), at, bar)
            drawRect(style.playerColor, at, bar.copy(width = bar.width * progress.coerceIn(0f, 1f)))
        }
        x += cell
        count++
    }

    if (run.vehicle != UfoVehicle.Saucer) indicator(
        0,
        progress = if (run.vehicle == UfoVehicle.Titan) run.vehicleTime / 18f else 0f
    )
    if (run.boost > 0f) indicator(1, run.boost / (450f + run.powerLevel * 130f))
    if (run.cash > 0f) indicator(3, run.cash / (500f + run.powerLevel * 90f))
    if (run.chrono > 0f) indicator(4, run.chrono / (6f + run.powerLevel * 1.5f))
    if (run.shield > 0) indicator(2, value = run.shield.toString())
    if (run.titanParts > 0) indicator(6, value = "${run.titanParts}/3")
    if (run.revive) indicator(9)
    if (run.blast) indicator(10)
    if (run.multiplier > 1) indicator(11, value = "×${run.multiplier}")

    var labelY = maxOf(38.dp.toPx(), y + 10.dp.toPx())
    for (gadget in run.gadgets) {
        val icon = UfoGadgetArt[gadget.ordinal]
        translate(inset, labelY) {
            scale(density * 0.5f, Offset.Zero) { drawUfoArt(icon, p, Offset.Zero) }
        }
        val layout = measurer.measure(
            labels.gadgets[gadget.ordinal], textStyle.copy(fontSize = 9.sp), maxLines = 1,
            overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis,
            constraints = androidx.compose.ui.unit.Constraints(maxWidth = (available - 16.dp.toPx()).toInt())
        )
        drawText(layout, p.text.copy(alpha = 0.75f), Offset(inset + 16.dp.toPx(), labelY))
        labelY += maxOf(layout.size.height.toFloat(), 12.dp.toPx()) + 2.dp.toPx()
    }
    if (run.bannerTime > 0f && run.banner / 100 != 2) {
        val label = labels.banner(run.banner)
        val layout = measurer.measure(
            label, textStyle, maxLines = 1,
            overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis,
            constraints = androidx.compose.ui.unit.Constraints(maxWidth = available.toInt())
        )
        val alpha = run.bannerTime.coerceAtMost(1f)
        val pad = 4.dp.toPx()
        drawRoundRect(
            p.hud.copy(alpha = 0.88f * alpha), Offset(inset - pad, labelY - pad / 2f),
            Size(layout.size.width + pad * 2f, layout.size.height + pad), CornerRadius(pad)
        )
        drawText(layout, p.text.copy(alpha = alpha), Offset(inset, labelY))
        labelY += layout.size.height + pad
    }
    if (run.bonusTime > 0f && run.bonusText > 0) {
        drawText(
            measurer, "+${run.bonusText}", topLeft = Offset(inset, labelY),
            style = textStyle.copy(
                color = style.accentColor.copy(
                    alpha = run.bonusTime.coerceAtMost(
                        1f
                    )
                )
            )
        )
    }
}

private enum class UfoVehicle {
    Saucer, Bike, Walker, Gravity, Teleporter, Bird, Dragon, Titan, Surfer, Sled
}

private enum class UfoGadget {
    Magnet, TokenMagnet, Crystals, Gift, Launch, Bounce, Ice, Ballast, SlowMissiles,
    EmptyLab, Jammer, Scanner, FreeRide, Lucky, Cargo, Discharger, Companion, Rings, Brick
}

private enum class UfoPickupKind { Coin, Crystal, Token, Vehicle, Boost, Shield, Cash, Chrono, Gadget, Part, Revive, Blast, Ring, Cargo }
private enum class UfoHazardKind { Zapper, Rotating, Missile, Laser }

@Serializable
private data class UfoHazard(
    val kind: UfoHazardKind,
    var x: Float,
    var y: Float,
    val length: Float = 38f,
    var angle: Float = 0f,
    val spin: Float = 0f,
    var age: Float = 0f,
    var passed: Boolean = false,
    var disabled: Boolean = false,
    var locked: Boolean = false
) {
    var trailTime = 0f
    val direction get() = Offset(cos(angle), sin(angle))
}

@Serializable
private data class UfoPickup(
    val kind: UfoPickupKind,
    var x: Float,
    var y: Float,
    val variant: Int = 0,
    var age: Float = 0f
) {
    var baseY = y
    var wavePhase = 0f
    var attracted = false
    val floating get() = kind != UfoPickupKind.Coin && kind != UfoPickupKind.Crystal && kind != UfoPickupKind.Ring
}

private class UfoParticle(
    var x: Float, var y: Float, var vx: Float, var vy: Float,
    var life: Float, val duration: Float, val kind: Int
)

private class UfoScientist(
    val id: Long, var x: Float, var y: Float, var vx: Float, var vy: Float,
    var angle: Float, var spin: Float, var age: Float = 0f
)

@Serializable
private class UfoJoyrideRun : ArcadeRun() {
    var seed = Random.nextInt()
    var travelled = 0.0
        private set
    var time = 0f
        private set
    var y = 100f
    var velocity = 0f
    var vehicle = UfoVehicle.Saucer
        private set
    var vehicleTime = 0f
        private set
    var tilt = 0f
        private set
    var shield = 0
        private set
    var titanParts = 0
        private set
    var titanArmor = 0
        private set
    var coins = 0
        private set
    var tokens = 0
        private set
    var streak = 0
        private set
    var nearMisses = 0
        private set
    var points = 0L
        private set
    var boost = 0f
        private set
    var cash = 0f
        private set
    var cashPigX = -100f
        private set
    var chrono = 0f
        private set
    var immunity = 0f
        private set
    var flash = 0f
        private set
    var shake = 0f
        private set
    var transforming = 0f
        private set
    var transfer = false
        private set
    var crashing = false
        private set
    var crashTime = 0f
        private set
    var revive = false
        private set
    var blast = false
        private set
    var banner = -1
        private set
    var bannerTime = 0f
        private set
    var bonusText = 0
        private set
    var bonusTime = 0f
        private set
    var message = 0
        private set
    val hazards = mutableListOf<UfoHazard>()
    val pickups = mutableListOf<UfoPickup>()
    val gadgets = mutableListOf<UfoGadget>()

    @Transient
    val particles = mutableListOf<UfoParticle>()

    @Transient
    val scientists = mutableListOf<UfoScientist>()

    @Transient
    var pressed = false
        private set
    private var fieldWidth = 480f
    private var fieldHeight = 220f
    private var fieldTop = 44f
    private var nextPattern = 900f
    private var nextVehicle = 1800f
    private var nextPower = 3000f
    private var nextGadget = 4500f
    private var nextPart = 1000f
    private var nextToken = 2500f
    private var nextUtility = 9000f
    private var nextCargo = 6500f
    private var nextRing = 6000f
    private var nextSpecial = 0f
    private var lastLane = 1
    private var lastPattern = -1
    private var vehicleIndex = 0
    private var powerIndex = 0
    private var gadgetIndex = 0
    private var powerCount = 0
    private var flip = 1f
    private var streakTime = 0f
    private var vehicleDistance = 0f
    private var jumpHeld = 0f
    private var crashVelocity = 0f
    private var crashBounces = 0
    private var particleTime = 0f
    private var coinStream = 0f
    private var chronoWave = 0f
    private var hitStop = 0f
    private var boostSpeed = 1f
    private var driveSpeed = 138f
    private var vehicleAge = 0f
    private var blinkOffset = 0f
    private var cashLane = 0f
    private var chronoVehicle = 0f
    var titanHand = 0f
        private set
    val playerX get() = (width * 0.36f).coerceIn(80f, 190f) + blinkOffset
    val ceiling get() = (topInset + 4f).coerceAtMost(height - 82f)
    val ground get() = height - 22f
    val flightScale get() = ((ground - ceiling) / 150f).coerceAtLeast(0.6f)
    val pickupAmplitude get() = ((ground - ceiling - 28f) * 0.26f).coerceIn(4f, 72f)
    val radiusX
        get() = when (vehicle) {
            UfoVehicle.Titan -> 21f
            UfoVehicle.Dragon -> 17f
            else -> 12f
        }
    val radiusY
        get() = when (vehicle) {
            UfoVehicle.Titan -> minOf(40f, (ground - ceiling) / 2f - 2f)
            UfoVehicle.Walker -> 24f
            UfoVehicle.Bike -> 22f
            UfoVehicle.Teleporter -> 20f
            UfoVehicle.Gravity, UfoVehicle.Sled, UfoVehicle.Dragon -> 18f
            UfoVehicle.Bird, UfoVehicle.Surfer -> 16f
            else -> 8f
        }
    val distance get() = (travelled * 0.1).toInt()
    val speed
        get() = ((138f + distance * 0.045f).coerceAtMost(248f) * when (vehicle) {
            UfoVehicle.Bike -> (1.15f + vehicleAge * 0.008f).coerceAtMost(1.45f)
            UfoVehicle.Walker -> 0.92f
            UfoVehicle.Surfer -> 1.12f
            UfoVehicle.Titan -> 1.08f
            else -> 1f
        })
            .coerceAtMost((width - playerX - 36f) / 1.15f)
    val cashPigY get() = cashLane + sin(time * 4f) * 6f
    val titanShieldY get() = ground - 18f - titanHand * 56f
    val targetY
        get() = ceiling + radiusY + 4f + (ground - ceiling - radiusY * 2f - 8f) *
                (0.5f + sin(time * 2.3f) * 0.5f)
    val powerLevel get() = (1 + powerCount / 4).coerceAtMost(5)
    val biome get() = (travelled / 2700.0).toInt() % 5
    val biomeBlend get() = ((travelled % 2700.0) / 350.0).toFloat().coerceAtMost(1f)
    val gravityUp get() = flip < 0f
    val multiplier get() = 1 + (streak / 10).coerceAtMost(4)

    fun has(gadget: UfoGadget) = gadget in gadgets

    private fun random(): Float {
        seed = seed * 1664525 + 1013904223
        return (seed ushr 8) / 16777216f
    }

    override fun reset() {
        fieldWidth = width
        fieldHeight = height
        fieldTop = topInset
        seed = Random.nextInt()
        travelled = 0.0
        time = 0f
        y = ground - 12f
        velocity = 0f
        vehicle = UfoVehicle.Saucer
        vehicleTime = 0f
        tilt = 0f
        shield = 0
        titanParts = 0
        titanArmor = 0
        coins = 0
        tokens = 0
        streak = 0
        nearMisses = 0
        points = 0L
        boost = 0f
        cash = 0f
        cashPigX = -100f
        chrono = 0f
        immunity = 0f
        flash = 0f
        shake = 0f
        transforming = 0f
        transfer = false
        crashing = false
        crashTime = 0f
        revive = false
        blast = false
        banner = -1
        bannerTime = 0f
        bonusText = 0
        bonusTime = 0f
        message = 0
        pressed = false
        nextPattern = 900f
        nextVehicle = 1800f
        nextPower = 3000f
        nextGadget = 4500f
        nextPart = 1000f
        nextToken = 2000f + random() * 2500f
        nextUtility = 9000f
        nextCargo = 6500f
        nextRing = 6000f
        nextSpecial = 0f
        lastLane = 1
        lastPattern = -1
        vehicleIndex = (random() * 6).toInt()
        powerIndex = (random() * 4).toInt()
        gadgetIndex = (random() * UfoGadget.entries.size).toInt()
        powerCount = 0
        flip = 1f
        streakTime = 0f
        vehicleDistance = 0f
        jumpHeld = 0f
        crashVelocity = 0f
        crashBounces = 0
        particleTime = 0f
        coinStream = 0f
        chronoWave = 0f
        hitStop = 0f
        boostSpeed = 1f
        vehicleAge = 0f
        blinkOffset = 0f
        driveSpeed = speed
        cashLane = (ceiling + ground) / 2f
        chronoVehicle = 0f
        titanHand = 0f
        hazards.clear()
        pickups.clear()
        gadgets.clear()
        particles.clear()
        scientists.clear()
        coinPattern(width + 24f, 2, 0)
        coinPattern(width + 400f, 2, 1)
        burst(playerX - 35f, ground - 20f, 10, 2)
    }

    override fun stopInput() {
        pressed = false
        jumpHeld = 0f
    }

    fun press() {
        if (crashing || phase != ArcadePhase.Running || pressed) return
        pressed = true
        val grounded = y >= ground - radiusY - 1f
        when (vehicle) {
            UfoVehicle.Gravity -> {
                flip = -flip
                velocity = flip * 90f * flightScale
                burst(playerX, y, 8, 1)
            }

            UfoVehicle.Teleporter -> {
                burst(playerX, y, 18, 1)
                y = targetY
                blinkOffset = (blinkOffset + 48f).coerceAtMost(
                    width - (width * 0.36f).coerceIn(
                        80f,
                        190f
                    ) - 40f
                )
                velocity = 0f
                immunity = maxOf(immunity, 0.18f)
                burst(playerX, y, 18, 1)
            }

            UfoVehicle.Bird, UfoVehicle.Surfer -> velocity = -165f * flightScale
            UfoVehicle.Bike -> if (grounded) {
                velocity = -220f * flightScale
                jumpHeld = 0.25f
            }

            UfoVehicle.Walker -> if (grounded) {
                velocity = -270f * flightScale
                jumpHeld = 0.38f
            }

            else -> if (grounded && has(UfoGadget.Launch)) velocity = -145f * flightScale
        }
    }

    override fun onRestore() {
        stopInput()
        particles.clear()
        scientists.clear()
    }

    override fun onResize(previous: Size) {
        val oldGround = fieldHeight - 22f
        val oldCeiling = (fieldTop + 4f).coerceAtMost(fieldHeight - 82f)
        val oldX = (fieldWidth * 0.36f).coerceIn(80f, 190f) + blinkOffset
        val delta = playerX - oldX
        val scaleY = (ground - ceiling) / (oldGround - oldCeiling).coerceAtLeast(1f)
        y = (ceiling + (y - oldCeiling) * scaleY).coerceIn(ceiling + radiusY, ground - radiusY)
        velocity *= scaleY
        cashLane =
            (ceiling + (cashLane - oldCeiling) * scaleY).coerceIn(ceiling + 16f, ground - 16f)
        if (cashPigX > -50f) cashPigX += delta
        hazards.forEach {
            it.x += delta; it.y = (ceiling + (it.y - oldCeiling) * scaleY).coerceIn(ceiling, ground)
        }
        for (pickup in pickups) {
            pickup.x += delta
            val offset = pickup.y - pickup.baseY
            val anchored = !pickup.floating && !pickup.attracted
            val edge = (oldGround - oldCeiling) * 0.35f
            val center = when {
                anchored && pickup.baseY - oldCeiling < edge -> ceiling + pickup.baseY - oldCeiling
                anchored && oldGround - pickup.baseY < edge -> ground - (oldGround - pickup.baseY)
                else -> ceiling + (pickup.baseY - oldCeiling) * scaleY
            }
            pickup.baseY = center.coerceIn(ceiling + 10f, ground - 10f)
            pickup.y = when {
                anchored -> pickup.baseY + offset
                pickup.floating && !pickup.attracted -> pickupY(pickup)
                else -> ceiling + (pickup.y - oldCeiling) * scaleY
            }.coerceIn(ceiling + 10f, ground - 10f)
        }
        fieldWidth = width
        fieldHeight = height
        fieldTop = topInset
        scientists.clear()
        immunity = maxOf(immunity, 1.2f)
        stopInput()
    }

    override fun isValid(): Boolean = super.isValid() && y.isFinite() && velocity.isFinite() &&
            travelled.isFinite() && travelled >= 0.0 && hazards.size <= 48 && pickups.size <= 180 &&
            gadgets.size <= 2 && gadgets.distinct().size == gadgets.size &&
            hazards.all { it.x.isFinite() && it.y.isFinite() && it.age.isFinite() } &&
            pickups.all { it.x.isFinite() && it.y.isFinite() }

    override fun advance(seconds: Float) {
        time += seconds
        flash = (flash - seconds * 2f).coerceAtLeast(0f)
        shake = (shake - seconds * 18f).coerceAtLeast(0f)
        bannerTime = (bannerTime - seconds).coerceAtLeast(0f)
        bonusTime = (bonusTime - seconds).coerceAtLeast(0f)
        transforming = (transforming - seconds).coerceAtLeast(0f)
        if (transforming == 0f) transfer = false
        advanceParticles(seconds)
        if (hitStop > 0f) {
            hitStop = (hitStop - seconds).coerceAtLeast(0f)
            return
        }
        if (crashing) {
            advanceCrash(seconds)
            return
        }
        immunity = (immunity - seconds).coerceAtLeast(0f)
        blinkOffset *= exp(-seconds * 7f)
        chrono = (chrono - seconds).coerceAtLeast(0f)
        streakTime = (streakTime - seconds).coerceAtLeast(0f)
        if (streakTime == 0f) streak = 0
        val dt = seconds * if (chrono > 0f) 0.5f else 1f
        val targetSpeed =
            if (boost > 0f) 1f + 2f * (boost / (speed * 0.75f)).coerceAtMost(1f) else 1f
        boostSpeed += (targetSpeed - boostSpeed) * (1f - exp(-seconds * 7f))
        driveSpeed += (speed - driveSpeed) * (1f - exp(-seconds * 3f))
        val moving = driveSpeed * boostSpeed
        val step = moving * dt
        travelled += step.toDouble()
        advanceScientists(dt, step)
        if (boost > 0f) {
            boost = (boost - step).coerceAtLeast(0f)
            if (boost == 0f) safeExit(1.25f)
        }
        if (cash > 0f) {
            cash = (cash - step).coerceAtLeast(0f)
            coinStream -= step
            if (coinStream <= 0f) {
                coinStream += 24f
                val cy = cashLane
                if (pickups.size < 150) for (row in -1..1) {
                    pickups += UfoPickup(
                        if (random() < 0.15f) UfoPickupKind.Crystal else UfoPickupKind.Coin,
                        width + 24f, (cy + row * 16f).coerceIn(ceiling + 10f, ground - 10f)
                    ).also { it.baseY = cy }
                }
            }
            if (cash == 0f) {
                safeExit(1f)
            }
        }
        if (cashPigX > -50f) {
            val previous = cashPigX
            cashPigX -= step
            if (segmentDistance(
                    playerX,
                    y,
                    previous,
                    cashPigY,
                    cashPigX,
                    cashPigY
                ) < radiusX + 16f && abs(cashPigY - y) < radiusY + 14f
            ) {
                cashBurst(cashPigX, cashPigY)
                cashPigX = -100f
                award(200 + powerLevel * 100, 0)
            }
        }
        if (chrono > 0f) {
            if (chronoVehicle > 0f) {
                chronoVehicle = (chronoVehicle - seconds).coerceAtLeast(0f)
                if (chronoVehicle == 0f && vehicle == UfoVehicle.Saucer) spawnPickup(
                    UfoPickupKind.Vehicle,
                    width + 24f,
                    vehicleIndex++ % 8
                )
            }
            chronoWave -= seconds
            if (chronoWave <= 0f && hazards.size < 28) {
                chronoWave = 2.4f
                hazards += UfoHazard(UfoHazardKind.Missile, width + 20f, y)
            }
        }
        val previousY = y
        advancePlayer(seconds)
        advanceHazards(dt, step)
        if (crashing) return
        advancePickups(dt, step, previousY)
        if (vehicle != UfoVehicle.Saucer) {
            vehicleAge += seconds
            if (vehicle == UfoVehicle.Titan) vehicleTime -= seconds
            vehicleDistance += step
            if (vehicleDistance >= 500f) {
                vehicleDistance -= 500f
                award(75, 2)
            }
            if (vehicle == UfoVehicle.Titan && vehicleTime <= 0f) transform(UfoVehicle.Saucer)
        }
        generate(step)
        particleTime -= seconds
        if (particleTime <= 0f) {
            particleTime = if (boost > 0f) 0.025f else 0.07f
            if (pressed || boost > 0f || vehicle == UfoVehicle.Dragon) {
                particle(playerX - 5f, y + radiusY, -25f, 30f, 0.45f, if (boost > 0f) 1 else 0)
            }
        }
        updateScore()
    }

    private fun advanceScientists(dt: Float, step: Float) {
        for (scientist in scientists) {
            scientist.x += scientist.vx * dt - step
            scientist.vy += 420f * dt
            scientist.y += scientist.vy * dt
            scientist.angle += scientist.spin * dt
            scientist.age += dt
            if (scientist.y >= ground - 5f) {
                scientist.y = ground - 5f
                scientist.vy = if (scientist.vy > 45f) -scientist.vy * 0.28f else 0f
                scientist.vx *= exp(-dt * 5f)
                scientist.spin *= exp(-dt * 6f)
            }
        }
        scientists.removeAll { it.x < -60f || it.age > 8f }
        val beam = pressed && vehicle == UfoVehicle.Saucer
        val flame = pressed && vehicle == UfoVehicle.Dragon && y > ground - 65f
        val impact = vehicle in listOf(
            UfoVehicle.Bike,
            UfoVehicle.Walker,
            UfoVehicle.Titan,
            UfoVehicle.Surfer,
            UfoVehicle.Sled
        ) && y >= ground - radiusY - 2f
        if ((!beam && !flame && !impact) || crashing || has(UfoGadget.EmptyLab) || scientists.size >= 12) return
        val hitX = playerX + if (flame) 30f else 0f
        val first = floor((travelled + hitX - 145.0) / 240.0).toLong()
        for (id in first..first + 1) {
            val x = (id * 240.0 - travelled + 145.0).toFloat()
            if (x > hitX + 12f || x + step < hitX - 12f || scientists.any { it.id == id }) continue
            val direction = if (id % 2L == 0L) -1f else 1f
            scientists += UfoScientist(
                id, x, ground - 5f, direction * (75f + (id % 3L).toInt() * 15f),
                -160f, direction * 18f, direction * 270f
            )
            burst(x, ground + 4f, 8, 2)
        }
    }

    private fun advancePlayer(dt: Float) {
        val bottom = ground - radiusY
        val top = ceiling + radiusY
        if (vehicle == UfoVehicle.Titan) {
            val target = if (pressed) 1f else 0f
            titanHand += (target - titanHand) * (1f - exp(-dt * 5f))
            y = bottom
            velocity = 0f
            tilt = 0f
            return
        }
        if (vehicle == UfoVehicle.Teleporter) {
            velocity = 0f
            tilt = 0f
            return
        }
        val wasGrounded = y >= bottom - 0.1f
        val acceleration = when (vehicle) {
            UfoVehicle.Gravity -> flip * 560f
            UfoVehicle.Bird, UfoVehicle.Surfer -> 380f
            UfoVehicle.Dragon -> if (pressed) 390f else -360f
            UfoVehicle.Sled -> if (pressed) -460f else 340f
            UfoVehicle.Bike, UfoVehicle.Walker ->
                if (pressed && jumpHeld > 0f) -140f else 600f

            else -> if (pressed) -760f else if (has(UfoGadget.Ballast)) 760f else 560f
        }
        jumpHeld = (jumpHeld - dt).coerceAtLeast(0f)
        velocity = if (vehicle == UfoVehicle.Saucer || vehicle == UfoVehicle.Sled) {
            val drag = if (vehicle == UfoVehicle.Sled) 2.1f else 3.4f
            val damping = exp(-dt * drag)
            velocity * damping + acceleration * flightScale * (1f - damping) / drag
        } else velocity + acceleration * flightScale * dt
        velocity = velocity.coerceIn(-240f * flightScale, 240f * flightScale)
        if (vehicle == UfoVehicle.Walker && pressed) velocity = minOf(velocity, 55f * flightScale)
        y = (y + velocity * dt).coerceIn(top, bottom)
        if (y == bottom && velocity > 0f) {
            if (!wasGrounded) {
                burst(playerX, ground, if (vehicle == UfoVehicle.Walker) 12 else 4, 2)
                if (vehicle == UfoVehicle.Walker) {
                    for (hazard in hazards) if (abs(hazard.x - playerX) < 55f && hazard.y > ground - 50f) destroy(
                        hazard,
                        10
                    )
                }
            }
            velocity = 0f
        }
        if (y == top && velocity < 0f) velocity = 0f
        val target = (velocity / flightScale * 0.045f).coerceIn(-10f, 12f)
        tilt += (target - tilt) * (1f - exp(-dt * 9f))
    }

    private fun advanceHazards(dt: Float, step: Float) {
        for (hazard in hazards) {
            val oldX = hazard.x
            val oldAngle = hazard.angle
            if (hazard.kind == UfoHazardKind.Missile) {
                hazard.age += dt
                if (hazard.age < 0.8f) {
                    if (vehicle != UfoVehicle.Titan) hazard.y += (y - hazard.y) * (1f - exp(-dt * 7f))
                } else if (!hazard.locked) {
                    hazard.locked = true
                    if (has(UfoGadget.Jammer) && random() < 0.3f) hazard.disabled = true
                }
                if (hazard.age > 1.15f) {
                    hazard.x -= dt * (if (has(UfoGadget.SlowMissiles)) 260f else 390f)
                    if (hazard.disabled) hazard.y += (hazard.age - 1.15f) * 170f * dt
                    else if (chrono > 0f) {
                        hazard.trailTime -= dt
                        if (hazard.trailTime <= 0f && pickups.size < 150) {
                            hazard.trailTime = 0.12f
                            pickups += UfoPickup(UfoPickupKind.Crystal, hazard.x + 18f, hazard.y)
                        }
                    }
                }
            } else {
                hazard.x -= step
                if (hazard.x < width + 10f) hazard.age += dt
                hazard.angle += hazard.spin * dt
            }
            if (hazard.disabled) continue
            val active = when (hazard.kind) {
                UfoHazardKind.Missile -> hazard.age > 1.15f
                UfoHazardKind.Laser -> hazard.age > 0.95f && hazard.age < 2.65f
                else -> true
            }
            if (!active) continue
            val radius = radiusY + 3f
            val collided = when (hazard.kind) {
                UfoHazardKind.Missile -> segmentDistance(
                    playerX, y, hazard.x - 12f, hazard.y, oldX + 12f, hazard.y
                ) < radius + 4f

                UfoHazardKind.Laser -> abs(hazard.y - y) < radius &&
                        playerX + radiusX > hazard.x - 90f && playerX - radiusX < oldX + 90f

                else -> {
                    val dx = cos(hazard.angle) * hazard.length / 2
                    val dy = sin(hazard.angle) * hazard.length / 2
                    val sweep =
                        abs(hazard.angle - oldAngle) * hazard.length / 2 + abs(oldX - hazard.x)
                    segmentDistance(
                        playerX,
                        y,
                        hazard.x - dx,
                        hazard.y - dy,
                        hazard.x + dx,
                        hazard.y + dy
                    ) < radius + sweep
                }
            }
            if (collided) {
                if (boost > 0f || cash > 0f) destroy(hazard, 10)
                else if (vehicle == UfoVehicle.Titan && hazard.kind == UfoHazardKind.Missile && abs(
                        hazard.y - titanShieldY
                    ) < 20f
                ) {
                    destroy(hazard, 60)
                    burst(playerX + 25f, y, 14, 1)
                } else if (immunity == 0f) {
                    destroy(hazard, 0)
                    damage()
                    if (crashing) break
                }
            } else if (!hazard.passed && hazard.x + hazard.length / 2 < playerX - radiusX) {
                hazard.passed = true
                if (abs(hazard.y - y) < hazard.length / 2 + radiusY + 22f) {
                    nearMisses++
                    award(10 * multiplier, 1)
                    if (nearMisses % 5 == 0) award(100, 1)
                }
            }
        }
        hazards.removeAll { it.x < -140f || it.kind == UfoHazardKind.Laser && it.age > 3f }
    }

    private fun damage() {
        flash = 0.3f
        shake = 4f
        hitStop = 0.045f
        streak = 0
        when {
            shield > 0 -> {
                shield--
                safeExit(0.85f)
                burst(playerX, y, 18, 1)
            }

            vehicle == UfoVehicle.Titan && titanArmor > 1 -> {
                titanArmor--
                safeExit(1.1f)
            }

            vehicle != UfoVehicle.Saucer -> {
                burst(playerX, y, 28, 2)
                transform(UfoVehicle.Saucer)
            }

            else -> {
                crashing = true
                crashTime = 0f
                crashVelocity = speed * if (blast) 3f else 0.7f
                velocity = if (blast) -200f else -100f
                if (blast) {
                    points += 100
                    burst(playerX, y, 35, 1)
                }
                blast = false
                crashBounces = if (has(UfoGadget.Bounce)) 4 else 1
                stopInput()
            }
        }
    }

    private fun advanceCrash(dt: Float) {
        crashTime += dt
        val step = crashVelocity * dt
        travelled += step
        advanceScientists(dt, step)
        hazards.forEach { it.x -= step }
        pickups.forEach { it.x -= step }
        velocity += 490f * dt
        y = (y + velocity * dt).coerceAtMost(ground - 6f)
        tilt += crashVelocity * dt
        if (y >= ground - 6f) {
            if (velocity > 30f && crashBounces > 0) {
                velocity *= if (has(UfoGadget.Bounce)) -0.8f else -0.35f
                crashBounces--
                burst(playerX, y, 8, 2)
            } else velocity = 0f
            crashVelocity *= exp(
                -dt * when {
                    has(UfoGadget.Brick) -> 12f
                    has(UfoGadget.Ice) -> 0.7f
                    else -> 3f
                }
            )
        } else crashVelocity *= exp(-dt * 0.25f)
        updateScore()
        if (crashTime > 0.9f && crashVelocity < 8f || crashTime > 4.5f) {
            if (revive) {
                revive = false
                crashing = false
                y = (ceiling + ground) / 2f
                velocity = 0f
                safeExit(2f)
                announce(3, 0)
                burst(playerX, y, 30, 1)
            } else {
                if (has(UfoGadget.Brick)) points += 75
                updateScore()
                finish()
            }
        }
    }

    private fun pickupY(pickup: UfoPickup): Float {
        val center =
            pickup.baseY.coerceIn(ceiling + pickupAmplitude + 14f, ground - pickupAmplitude - 14f)
        return center + sin(pickup.age * 2.15f + pickup.wavePhase) * pickupAmplitude
    }

    private fun advancePickups(dt: Float, step: Float, previousY: Float) {
        val iterator = pickups.iterator()
        while (iterator.hasNext()) {
            val pickup = iterator.next()
            val oldX = pickup.x
            val oldY = pickup.y
            pickup.x -= step
            pickup.age += dt
            if (!pickup.attracted && pickup.floating) pickup.y = pickupY(pickup)
            val money = pickup.kind == UfoPickupKind.Coin || pickup.kind == UfoPickupKind.Crystal
            val reach = when {
                money && has(UfoGadget.Magnet) -> 64f
                money && vehicle != UfoVehicle.Saucer -> 38f
                pickup.kind == UfoPickupKind.Token && has(UfoGadget.TokenMagnet) -> 80f
                else -> 0f
            }
            val dogX = playerX - 48f
            val dogY = ground - 6f
            val fetch = money && has(UfoGadget.Companion) &&
                    abs(pickup.x - dogX) < 64f && abs(pickup.y - dogY) < 38f
            if (fetch || reach > 0f && abs(pickup.x - playerX) < reach && abs(pickup.y - y) < reach) {
                pickup.attracted = true
                val factor = 1f - exp(-dt * 13f)
                pickup.x += ((if (fetch) dogX else playerX) - pickup.x) * factor
                pickup.y += ((if (fetch) dogY else y) - pickup.y) * factor
            }
            val radius = if (money) 8f else 10f
            val rx = radiusX + radius
            val ry = radiusY + radius
            val collected = segmentDistance(
                0f, 0f,
                (oldX - playerX) / rx, (oldY - previousY) / ry,
                (pickup.x - playerX) / rx, (pickup.y - y) / ry
            ) <= 1f ||
                    fetch && segmentDistance(dogX, dogY, oldX, oldY, pickup.x, pickup.y) < 13f
            if (pickup.x < -25f) iterator.remove()
            else if (vehicle != UfoVehicle.Saucer && pickup.kind in listOf(
                    UfoPickupKind.Boost,
                    UfoPickupKind.Shield,
                    UfoPickupKind.Cash,
                    UfoPickupKind.Chrono
                )
            ) iterator.remove()
            else if (collected) {
                iterator.remove()
                collect(pickup)
            }
        }
    }

    private fun collect(pickup: UfoPickup) {
        burst(pickup.x, pickup.y, if (pickup.kind == UfoPickupKind.Coin) 3 else 12, 1)
        when (pickup.kind) {
            UfoPickupKind.Coin, UfoPickupKind.Crystal -> {
                val crystal = pickup.kind == UfoPickupKind.Crystal
                coins += if (crystal) 5 else 1
                points += (if (crystal) 25 else 5) * multiplier
                streak++
                streakTime = 1.8f
                if (streak % 10 == 0) award(50 * multiplier, 0)
                if (coins / 25 > (coins - if (crystal) 5 else 1) / 25) award(100, 0)
            }

            UfoPickupKind.Token -> {
                tokens++
                award(if (has(UfoGadget.Lucky)) 250 else 100, 0)
            }

            UfoPickupKind.Vehicle -> transform(vehicleAt(pickup.variant))
            UfoPickupKind.Boost -> {
                powerCount++
                boost = 450f + powerLevel * 130f
                safeExit(1f)
                announce(1, 0)
            }

            UfoPickupKind.Shield -> {
                powerCount++
                shield = (shield + powerLevel).coerceAtMost(5)
                announce(1, 1)
            }

            UfoPickupKind.Cash -> {
                powerCount++
                cash = 500f + powerLevel * 90f
                cashLane = y.coerceIn(ceiling + 32f, ground - 32f)
                cashPigX = maxOf(width + 32f, playerX + cash + 32f)
                safeExit(1f)
                announce(1, 2)
            }

            UfoPickupKind.Chrono -> {
                powerCount++
                chrono = 6f + powerLevel * 1.5f
                chronoWave = 0.8f
                chronoVehicle = 0.6f
                announce(1, 3)
            }

            UfoPickupKind.Gadget -> equip(UfoGadget.entries[pickup.variant % UfoGadget.entries.size])
            UfoPickupKind.Part -> {
                titanParts++
                award(50, 0)
                if (titanParts >= 3) {
                    titanParts = 0
                    transform(UfoVehicle.Titan)
                }
            }

            UfoPickupKind.Revive -> {
                if (revive) award(150, 0)
                revive = true
                announce(3, 0)
            }

            UfoPickupKind.Blast -> {
                if (blast) award(100, 0)
                blast = true
                announce(3, 1)
            }

            UfoPickupKind.Ring -> {
                boost = maxOf(boost, 100f)
                immunity = maxOf(immunity, 0.8f)
                award(20, 0)
            }

            UfoPickupKind.Cargo -> {
                coins += 12
                cashBurst(pickup.x, pickup.y)
                award(100, 0)
            }
        }
        updateScore()
    }

    private fun equip(gadget: UfoGadget) {
        gadgets.remove(gadget)
        if (gadgets.size == 2) gadgets.removeAt(0)
        gadgets += gadget
        announce(2, gadget.ordinal)
        when (gadget) {
            UfoGadget.Gift -> {
                tokens++; points += 100
            }

            UfoGadget.FreeRide -> transform(vehicleAt(vehicleIndex++))
            else -> Unit
        }
        updateScore()
    }

    private fun transform(next: UfoVehicle) {
        transfer = vehicle == UfoVehicle.Saucer && next != UfoVehicle.Saucer
        vehicle = next
        vehicleAge = 0f
        blinkOffset = 0f
        titanHand = 0f
        vehicleTime = if (next == UfoVehicle.Titan) 18f else 22f
        vehicleDistance = 0f
        titanArmor = if (next == UfoVehicle.Titan) 3 else 0
        velocity = 0f
        flip = 1f
        y = y.coerceIn(ceiling + radiusY + 2f, ground - radiusY - 2f)
        transforming = 0.65f
        safeExit(1.5f)
        burst(playerX, y, 24, 2)
        if (next != UfoVehicle.Saucer) announce(0, next.ordinal)
        jumpHeld = 0f
    }

    private fun safeExit(seconds: Float) {
        immunity = maxOf(immunity, seconds)
        val clearTo = playerX + speed * seconds + 80f
        for (hazard in hazards) if (hazard.x in playerX - 100f..clearTo) hazard.disabled = true
        nextPattern = maxOf(nextPattern, speed * seconds)
        flash = maxOf(flash, 0.12f)
    }

    private fun award(value: Int, type: Int) {
        points += value
        bonusText = value
        bonusTime = 1f
        message = type
        updateScore()
    }

    private fun updateScore() {
        score = (distance.toLong() + points).coerceIn(0, Int.MAX_VALUE.toLong()).toInt()
    }

    private fun announce(type: Int, index: Int) {
        banner = type * 100 + index
        bannerTime = 2.4f
        bonusText = 0
    }

    private fun destroy(hazard: UfoHazard, value: Int) {
        if (hazard.disabled) return
        hazard.disabled = true
        burst(hazard.x.coerceAtMost(width), hazard.y, 12, 2)
        if (value > 0) award(value, 1)
    }

    private fun vehicleAt(index: Int) = when (val selected = index % 8) {
        6 -> UfoVehicle.Surfer
        7 -> UfoVehicle.Sled
        else -> UfoVehicle.entries[1 + selected]
    }

    private fun lane(index: Int) =
        ceiling + 22f + (ground - ceiling - 44f).coerceAtLeast(0f) * index / 2f

    private fun coinPattern(x: Float, laneIndex: Int, variant: Int) {
        if (pickups.size > 145) return
        val gap = minOf(20f, (ground - ceiling - 28f) / 4f)
        val margin = minOf(
            (if (variant % 4 == 2) gap * 2f else gap) + 12f,
            (ground - ceiling) / 2f - 1f
        )
        val middle = lane(laneIndex).coerceIn(ceiling + margin, ground - margin)
        fun add(column: Int, y: Float) {
            val kind =
                if (has(UfoGadget.Crystals) && random() < 0.2f) UfoPickupKind.Crystal else UfoPickupKind.Coin
            pickups += UfoPickup(
                kind, x + column * gap,
                y.coerceIn(ceiling + 12f, ground - 12f)
            ).also { it.baseY = middle }
        }
        when (variant % 4) {
            0 -> for (column in 0..6) for (row in -1..1) {
                add(column, middle + row * gap)
            }

            1 -> for (column in 0..7) {
                val rise = sin(column / 7f * PI.toFloat()) * minOf(42f, (ground - ceiling) * 0.2f)
                for (row in 0..1) add(column, middle - rise + row * gap)
            }

            2 -> for (column in 0..6) {
                val spread = minOf(column, 6 - column, 2)
                for (row in -spread..spread) add(column, middle + row * gap)
            }

            else -> for (column in 0..7) for (row in -1..1) {
                val wave = sin(column / 7f * PI.toFloat() * 2f) * 16f
                add(column, middle + wave + row * gap)
            }
        }
    }

    private fun generate(step: Float) {
        nextPattern -= step
        nextVehicle -= step
        nextPower -= step
        nextGadget -= step
        nextPart -= step
        nextToken -= step
        nextUtility -= step
        nextCargo -= step
        nextRing -= step
        val spawn = width + 200f
        if (nextPattern <= 0f && hazards.size < 32 && pickups.size < 130) {
            nextPattern += maxOf(260f, speed * 1.7f) + random() * 80f
            if (vehicle == UfoVehicle.Titan) {
                hazards += UfoHazard(
                    UfoHazardKind.Missile,
                    width + 20f,
                    ground - 22f - random() * 48f
                )
            } else if (cash <= 0f) pattern(spawn)
        }
        nextSpecial = (nextSpecial - step).coerceAtLeast(0f)
        if (nextSpecial > 0f || boost > 0f || cash > 0f || chrono > 0f) return
        when {
            nextVehicle <= 0f && vehicle == UfoVehicle.Saucer -> {
                nextVehicle = 5500f + random() * 2000f
                spawnPickup(UfoPickupKind.Vehicle, spawn, vehicleIndex++ % 8)
            }

            nextPower <= 0f && vehicle == UfoVehicle.Saucer -> {
                nextPower = 5000f + random() * 5000f
                val kind = when (powerIndex++ % 4) {
                    0 -> UfoPickupKind.Boost
                    1 -> UfoPickupKind.Shield
                    2 -> UfoPickupKind.Cash
                    else -> UfoPickupKind.Chrono
                }
                spawnPickup(kind, spawn)
            }

            nextPart <= 0f && vehicle != UfoVehicle.Titan -> {
                nextPart = 5000f + random() * 1000f
                spawnPickup(UfoPickupKind.Part, spawn, titanParts)
            }

            nextToken <= 0f -> {
                nextToken = 3500f + random() * 4500f
                spawnPickup(UfoPickupKind.Token, spawn)
            }

            nextGadget <= 0f -> {
                nextGadget = 7000f + random() * 3000f
                spawnPickup(UfoPickupKind.Gadget, spawn, gadgetIndex++ % UfoGadget.entries.size)
            }

            nextUtility <= 0f -> {
                nextUtility = 12000f + random() * 4000f
                spawnPickup(
                    if (random() < 0.5f) UfoPickupKind.Revive else UfoPickupKind.Blast,
                    spawn
                )
            }

            has(UfoGadget.Cargo) && nextCargo <= 0f -> {
                nextCargo = 6500f
                spawnPickup(UfoPickupKind.Cargo, spawn)
            }

            has(UfoGadget.Rings) && nextRing <= 0f -> {
                nextRing = 6000f
                for (i in 0..2) pickups += UfoPickup(
                    UfoPickupKind.Ring,
                    spawn + i * 55f,
                    lane(lastLane)
                )
            }

            else -> return
        }
        nextSpecial = 1100f + random() * 400f
    }

    private fun spawnPickup(kind: UfoPickupKind, x: Float, variant: Int = 0) {
        val py = (ceiling + ground) / 2f
        val previous =
            pickups.filter { it.kind !in listOf(UfoPickupKind.Coin, UfoPickupKind.Crystal) }
                .maxOfOrNull { it.x }
        val spacing = maxOf(130f, speed * 1.1f)
        val spawnX = maxOf(x, (previous ?: (x - spacing)) + spacing)
        pickups += UfoPickup(kind, spawnX, py, variant).also {
            it.wavePhase = random() * 2f * PI.toFloat()
            it.y = pickupY(it)
        }
        // A reward capsule must not share its approach with an earlier attack.
        for (hazard in hazards) if (abs(hazard.x - spawnX) < 140f && abs(hazard.y - py) < pickupAmplitude + hazard.length / 2f + 35f) hazard.disabled =
            true
    }

    private fun pattern(x: Float) {
        val nextLane = (lastLane + (if (random() < 0.5f) -1 else 1)).coerceIn(0, 2)
        val available = (ground - ceiling - 40f).coerceAtLeast(36f)
        val variant = ((random() * 11).toInt() + lastPattern + 1) % 12
        lastPattern = variant
        val other = if (nextLane == 0) 2 else 0
        val length = minOf(
            available * (0.3f + variant % 3 * 0.06f),
            80f * sqrt(flightScale).coerceAtMost(1.7f)
        )
        val hazardY = lane(other).coerceIn(ceiling + length / 2f + 12f, ground - length / 2f - 12f)
        val angle = when (variant) {
            0 -> PI.toFloat() / 2
            1 -> 0f
            2 -> PI.toFloat() / 4
            3 -> -PI.toFloat() / 4
            else -> PI.toFloat() / 2
        }
        val groundVehicle = vehicle in listOf(UfoVehicle.Bike, UfoVehicle.Walker, UfoVehicle.Surfer)
        when {
            groundVehicle -> {
                hazards += UfoHazard(UfoHazardKind.Zapper, x, ground - 16f, 22f, PI.toFloat() / 2)
                for (i in 0..6) {
                    val t = i / 6f
                    val kind =
                        if (has(UfoGadget.Crystals) && random() < 0.2f) UfoPickupKind.Crystal else UfoPickupKind.Coin
                    pickups += UfoPickup(
                        kind,
                        x - 75f + i * 25f,
                        ground - 24f - sin(t * PI.toFloat()) * 65f
                    ).also { it.baseY = ground - 24f }
                }
            }

            variant in listOf(4, 10) && distance > 80 -> {
                hazards += UfoHazard(UfoHazardKind.Missile, width + 20f, y)
                if (variant == 10 && distance > 300) {
                    hazards += UfoHazard(UfoHazardKind.Missile, width + 35f, y, age = -0.65f)
                }
            }

            variant in listOf(5, 11) && distance > 150 -> {
                hazards += UfoHazard(UfoHazardKind.Laser, x, hazardY, 80f)
                if (variant == 11 && distance > 450) {
                    val secondLane = (0..2).first { it != nextLane && it != other }
                    hazards += UfoHazard(UfoHazardKind.Laser, x, lane(secondLane), 80f)
                }
            }

            variant == 8 && nextLane == 1 -> {
                for (edge in intArrayOf(0, 2)) hazards += UfoHazard(
                    UfoHazardKind.Zapper,
                    x,
                    lane(edge).coerceIn(
                        ceiling + length * 0.35f + 12f,
                        ground - length * 0.35f - 12f
                    ),
                    length * 0.7f,
                    PI.toFloat() / 2
                )
            }

            else -> {
                val rotating = variant in listOf(3, 6, 9) && distance > 100
                val hazard = UfoHazard(
                    if (rotating) UfoHazardKind.Rotating else UfoHazardKind.Zapper, x, hazardY,
                    length, angle, if (rotating) (if (variant == 9) -1.4f else 1.4f) else 0f
                )
                if (has(UfoGadget.Discharger) && random() < 0.25f) hazard.disabled = true
                hazards += hazard
                if (distance > 220 && variant in listOf(1, 7)) {
                    hazards += UfoHazard(
                        UfoHazardKind.Zapper,
                        x + 70f,
                        hazardY,
                        length * 0.7f,
                        -angle
                    )
                }
            }
        }
        if (!groundVehicle) coinPattern(x - 145f, nextLane, variant)
        for (hazard in hazards) {
            if (pickups.any { pickup ->
                    pickup.kind !in listOf(UfoPickupKind.Coin, UfoPickupKind.Crystal) &&
                            abs(pickup.x - hazard.x) < 140f &&
                            abs(pickup.baseY - hazard.y) < hazard.length / 2 + pickupAmplitude + 35f
                }) hazard.disabled = true
        }
        lastLane = nextLane
    }

    private fun particle(x: Float, y: Float, vx: Float, vy: Float, life: Float, kind: Int) {
        if (particles.size >= 120) particles.removeAt(0)
        particles += UfoParticle(x, y, vx, vy, life, life, kind)
    }

    private fun cashBurst(x: Float, y: Float) {
        repeat(20) { index ->
            val angle = index * PI.toFloat() / 10f
            particle(x, y, cos(angle) * (60f + index % 4 * 18f), sin(angle) * 80f - 60f, 0.9f, 3)
        }
    }

    private fun burst(x: Float, y: Float, count: Int, kind: Int) {
        repeat(count) { index ->
            val angle = index * 2f * PI.toFloat() / count
            val speed = 20f + index % 5 * 12f
            particle(x, y, cos(angle) * speed, sin(angle) * speed, 0.35f + index % 4 * 0.1f, kind)
        }
    }

    private fun advanceParticles(dt: Float) {
        for (particle in particles) {
            particle.x += particle.vx * dt
            particle.y += particle.vy * dt
            if (particle.kind == 2 || particle.kind == 3) particle.vy += 150f * dt
            particle.life -= dt
        }
        particles.removeAll { it.life <= 0f }
    }
}

private fun segmentDistance(
    px: Float,
    py: Float,
    ax: Float,
    ay: Float,
    bx: Float,
    by: Float
): Float {
    val dx = bx - ax
    val dy = by - ay
    val length = dx * dx + dy * dy
    val t = if (length > 0f) ((px - ax) * dx + (py - ay) * dy) / length else 0f
    val x = px - ax - dx * t.coerceIn(0f, 1f)
    val y = py - ay - dy * t.coerceIn(0f, 1f)
    return sqrt(x * x + y * y)
}